// This helper will attempt to simulate tapping the Cancel button on the dialog
func simulateTap() {
    if let window = UIApplication.shared.connectedScenes
        .compactMap({ $0 as? UIWindowScene })
        .first?.windows.first(where: { $0.isKeyWindow }) {

        // Try to find and tap Cancel button
        let tap = UITapGestureRecognizer(target: self, action: nil)

        // Walk through view hierarchy to find the Cancel button
        if let buttons = window.rootViewController?.view.subviews.compactMap({ v -> UIButton? in
            if let btn = v as? UIButton, btn.titleLabel?.text == "Cancel" {
                return btn
            }
            return nil
        }) {
            if let cancelBtn = buttons.first {
                cancelBtn.sendActions(for: .touchUpInside)
            }
        }
    }
}

